insert into public.courses (id, slug, title, short_title, exam, subject, description, hue, exam_month, position) values
  ('ap-calculus-bc', 'ap-calculus-bc', 'AP Calculus BC', 'Calc BC', 'AP', 'Math', 'Limits through infinite series. Everything in AB, plus parametric, polar, and vector motion, and the series unit that decides most 5s.', 232, 'May', 0),
  ('ap-world-history', 'ap-world-history', 'AP World History: Modern', 'AP World', 'AP', 'History', '1200 to the present through networks of exchange, state building, revolution, and global conflict. It''s built around the reasoning the DBQ and LEQ reward.', 28, 'May', 1),
  ('sat-math', 'sat-math', 'SAT Math', 'SAT Math', 'SAT', 'Math', 'The four domains of the digital SAT: Algebra, Advanced Math, Problem-Solving and Data Analysis, and Geometry and Trigonometry. Taught for speed and for Desmos.', 160, 'Mar · May · Jun · Aug · Oct · Nov · Dec', 2),
  ('ap-biology', 'ap-biology', 'AP Biology', 'AP Bio', 'AP', 'Science', 'From cells to ecosystems, taught through the four big ideas: evolution, energetics, information storage, and systems interactions.', 140, 'May', 3),
  ('ap-chemistry', 'ap-chemistry', 'AP Chemistry', 'AP Chem', 'AP', 'Science', 'Atomic structure through thermodynamics, with the quantitative reasoning and particle-level explanations the free response requires.', 196, 'May', 4),
  ('sat-reading-writing', 'sat-reading-writing', 'SAT Reading and Writing', 'SAT R&W', 'SAT', 'English', 'Short passages and one question each. Vocabulary in context, evidence, structure, and the grammar rules that come up again and again.', 330, 'Mar · May · Jun · Aug · Oct · Nov · Dec', 5)
insert into public.units (id, course_id, slug, title, summary, position) values
  ('ap-calculus-bc/limits-and-continuity', 'ap-calculus-bc', 'limits-and-continuity', 'Limits and Continuity', 'What a function approaches, and when it actually gets there.', 1),
  ('ap-calculus-bc/differentiation', 'ap-calculus-bc', 'differentiation', 'Differentiation', 'Rates of change, and the rules that make them fast to compute.', 2),
  ('ap-calculus-bc/integration', 'ap-calculus-bc', 'integration', 'Integration and Accumulation', 'Adding up infinitely many tiny pieces, and how that connects back to derivatives.', 3),
  ('ap-calculus-bc/differential-equations', 'ap-calculus-bc', 'differential-equations', 'Differential Equations', 'Equations about rates, and the functions that satisfy them.', 4),
  ('ap-calculus-bc/parametric-polar-vector', 'ap-calculus-bc', 'parametric-polar-vector', 'Parametric, Polar, and Vector Functions', 'Curves described by time, by angle, and by direction.', 5),
  ('ap-calculus-bc/infinite-series', 'ap-calculus-bc', 'infinite-series', 'Infinite Sequences and Series', 'When adding infinitely many terms gives a finite answer, and how to use that.', 6),
  ('ap-world-history/global-tapestry', 'ap-world-history', 'global-tapestry', 'The Global Tapestry, 1200–1450', 'How states across Afro-Eurasia and the Americas organized power and belief.', 1),
  ('ap-world-history/networks-of-exchange', 'ap-world-history', 'networks-of-exchange', 'Networks of Exchange', 'Silk Roads, the Indian Ocean, and the Mongol moment.', 2),
  ('ap-world-history/land-based-empires', 'ap-world-history', 'land-based-empires', 'Land-Based Empires, 1450–1750', 'Gunpowder, legitimacy, and how empires held diverse populations together.', 3),
  ('ap-world-history/transoceanic-interconnections', 'ap-world-history', 'transoceanic-interconnections', 'Transoceanic Interconnections', 'Maritime empires, the Columbian Exchange, and coerced labor.', 4),
  ('ap-world-history/revolutions', 'ap-world-history', 'revolutions', 'Revolutions, 1750–1900', 'New ideas about government, and new ways of making things.', 5),
  ('ap-world-history/consequences-of-industrialization', 'ap-world-history', 'consequences-of-industrialization', 'Consequences of Industrialization', 'Imperialism, migration, and the states that reformed to compete.', 6),
  ('ap-world-history/global-conflict', 'ap-world-history', 'global-conflict', 'Global Conflict and Cold War', 'Two world wars, then a divided world and decolonization.', 7),
  ('sat-math/algebra', 'sat-math', 'algebra', 'Algebra', 'Linear equations, systems, and inequalities. About 35% of the test.', 1),
  ('sat-math/advanced-math', 'sat-math', 'advanced-math', 'Advanced Math', 'Quadratics, exponentials, and function behavior. About 35% of the test.', 2),
  ('sat-math/problem-solving-data', 'sat-math', 'problem-solving-data', 'Problem-Solving and Data Analysis', 'Ratios, percents, statistics, and probability. About 15% of the test.', 3),
  ('sat-math/geometry-trig', 'sat-math', 'geometry-trig', 'Geometry and Trigonometry', 'Area, volume, triangles, circles, and right-triangle trig. About 15% of the test.', 4),
  ('ap-biology/cellular-energetics', 'ap-biology', 'cellular-energetics', 'Cellular Energetics', 'Enzymes, photosynthesis, and respiration: how cells capture and spend energy.', 1),
  ('ap-biology/heredity', 'ap-biology', 'heredity', 'Heredity', 'Meiosis, Mendel, and the math of inheritance.', 2),
  ('ap-biology/gene-expression', 'ap-biology', 'gene-expression', 'Gene Expression and Regulation', 'DNA to RNA to protein, and how cells control it.', 3),
  ('ap-biology/natural-selection', 'ap-biology', 'natural-selection', 'Natural Selection', 'Evolution, population genetics, and the evidence behind it.', 4),
  ('ap-chemistry/atomic-structure', 'ap-chemistry', 'atomic-structure', 'Atomic Structure and Properties', 'Electrons, spectra, and periodic trends.', 1),
  ('ap-chemistry/bonding', 'ap-chemistry', 'bonding', 'Molecular Structure and Properties', 'Lewis structures, geometry, and the forces between molecules.', 2),
  ('ap-chemistry/equilibrium', 'ap-chemistry', 'equilibrium', 'Equilibrium', 'Reversible reactions and how systems respond to stress.', 3),
  ('ap-chemistry/acids-bases', 'ap-chemistry', 'acids-bases', 'Acids and Bases', 'pH, titrations, and buffers.', 4),
  ('ap-chemistry/thermodynamics', 'ap-chemistry', 'thermodynamics', 'Thermodynamics', 'Enthalpy, entropy, and whether a reaction happens on its own.', 5),
  ('sat-reading-writing/craft-and-structure', 'sat-reading-writing', 'craft-and-structure', 'Craft and Structure', 'Words in context, text structure, and cross-text connections.', 1),
  ('sat-reading-writing/information-and-ideas', 'sat-reading-writing', 'information-and-ideas', 'Information and Ideas', 'Central ideas, inferences, and evidence, including from data.', 2),
  ('sat-reading-writing/standard-english-conventions', 'sat-reading-writing', 'standard-english-conventions', 'Standard English Conventions', 'Boundaries, form, structure, and sense. These are the fastest points on the test.', 3)
