insert into public.topics (id, concept_id, unit_id, course_id, slug, title, summary, glyph, key_points, aliases, position) values
  ('limit-definition', 'ap-calculus-bc/limits-and-continuity/1', 'ap-calculus-bc/limits-and-continuity', 'ap-calculus-bc', 'limit-definition', 'What a Limit Means', 'A limit is the value a function approaches as the input gets close to a point. The function never has to reach it, and it doesn''t even have to be defined there.', 'lim x→a', array['Approach, not arrival', 'Reading limits from graphs and tables', 'When a limit does not exist']::text[], array['limits', 'limit intuition', 'limit notation']::text[], 1),
  ('limits-at-infinity', 'ap-calculus-bc/limits-and-continuity/1', 'ap-calculus-bc/limits-and-continuity', 'ap-calculus-bc', 'limits-at-infinity', 'Limits at Infinity', 'Limits at infinity describe end behavior. For rational functions, compare the highest powers in the numerator and denominator.', 'x→∞', array['Horizontal asymptotes', 'Dominant terms', 'Growth rates: log < poly < exp']::text[], array['end behavior', 'horizontal asymptote']::text[], 2),
  ('squeeze-theorem', 'ap-calculus-bc/limits-and-continuity/1', 'ap-calculus-bc/limits-and-continuity', 'ap-calculus-bc', 'squeeze-theorem', 'The Squeeze Theorem', 'If a function is trapped between two functions that approach the same limit, it has to approach that limit too. It''s the standard way to prove sin(x)/x → 1.', 'g ≤ f ≤ h', array['Building the bounds', 'sin(x)/x as x→0', 'Writing the justification']::text[], array['sandwich theorem']::text[], 3),
  ('types-of-discontinuity', 'ap-calculus-bc/limits-and-continuity/2', 'ap-calculus-bc/limits-and-continuity', 'ap-calculus-bc', 'types-of-discontinuity', 'Types of Discontinuity', 'Discontinuities come in three kinds: removable (a hole), jump, and infinite. Each one breaks a different part of the three-part definition of continuity.', '○ ●', array['The three conditions', 'Holes vs. jumps vs. asymptotes', 'Fixing a removable discontinuity']::text[], array['removable discontinuity', 'jump discontinuity', 'continuity']::text[], 4),
  ('intermediate-value-theorem', 'ap-calculus-bc/limits-and-continuity/2', 'ap-calculus-bc/limits-and-continuity', 'ap-calculus-bc', 'intermediate-value-theorem', 'Intermediate Value Theorem', 'A continuous function on a closed interval takes every value between its endpoint values. The IVT guarantees a solution exists but doesn''t tell you where it is.', 'f(c) = k', array['Hypotheses you must state', 'Existence, not location', 'Free-response phrasing']::text[], array['IVT']::text[], 5),
  ('power-rule', 'ap-calculus-bc/differentiation/1', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'power-rule', 'The Power Rule', 'To differentiate xⁿ, bring the exponent down and subtract one from it. It works for any real exponent, so rewrite roots and fractions as powers first.', 'nxⁿ⁻¹', array['Rewriting radicals as exponents', 'Negative and fractional powers', 'Linearity of the derivative']::text[], array['derivative of x^n', 'basic derivatives']::text[], 6),
  ('product-and-quotient-rules', 'ap-calculus-bc/differentiation/1', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'product-and-quotient-rules', 'Product and Quotient Rules', 'The derivative of a product isn''t the product of the derivatives. The product rule and quotient rule tell you how two changing factors combine.', 'f′g + fg′', array['Product rule pattern', 'Low d-high minus high d-low', 'When to simplify first instead']::text[], array['product rule', 'quotient rule']::text[], 7),
  ('chain-rule', 'ap-calculus-bc/differentiation/1', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'chain-rule', 'Chain Rule', 'The chain rule differentiates a composition. Take the derivative of the outside function, keep the inside the same, then multiply by the derivative of the inside.', 'f(g(x))′', array['Spotting the inner function', 'Outside-in, then multiply', 'Chains of three or more']::text[], array['composite functions', 'derivative of composition', 'chain']::text[], 8),
  ('implicit-differentiation', 'ap-calculus-bc/differentiation/2', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'implicit-differentiation', 'Implicit Differentiation', 'When y isn''t isolated, differentiate both sides with respect to x and treat y as a function of x. Every y term picks up a dy/dx.', 'dy/dx', array['Why y gets a dy/dx', 'Solving for dy/dx', 'Second derivatives implicitly']::text[], array['implicit', 'implicitly defined functions']::text[], 9),
  ('inverse-function-derivatives', 'ap-calculus-bc/differentiation/2', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'inverse-function-derivatives', 'Derivatives of Inverse Functions', 'At corresponding points, the slope of an inverse function is the reciprocal of the original function''s slope. Swap the coordinates, then flip the slope.', '1 / f′(g(x))', array['Corresponding points', 'The reciprocal-slope formula', 'Inverse trig derivatives']::text[], array['inverse derivative', 'arcsin derivative', 'inverse trig']::text[], 10),
  ('related-rates', 'ap-calculus-bc/differentiation/3', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'related-rates', 'Related Rates', 'When two quantities are linked by an equation and both change over time, differentiate with respect to t to connect their rates. Plug in the numbers only at the end.', 'dV/dt', array['Draw, label, relate', 'Differentiate before substituting', 'Ladders, cones, and shadows']::text[], array['rates of change', 'ladder problem', 'cone problem']::text[], 11),
  ('mean-value-theorem', 'ap-calculus-bc/differentiation/3', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'mean-value-theorem', 'Mean Value Theorem', 'Somewhere on a smooth interval, the instantaneous rate of change equals the average rate of change. Continuity and differentiability are the entry fee.', 'f′(c)', array['Secant slope equals tangent slope', 'Checking the hypotheses', 'MVT vs. IVT on the exam']::text[], array['MVT', 'Rolle''s theorem']::text[], 12),
  ('optimization', 'ap-calculus-bc/differentiation/3', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'optimization', 'Optimization', 'Optimization problems ask for the biggest or smallest possible value. Write the quantity as a function of one variable, find its critical points, and justify the extremum.', 'max / min', array['Constraint to one variable', 'Candidates test', 'Justifying with the first derivative']::text[], array['max min problems', 'extrema', 'absolute maximum']::text[], 13),
  ('lhopitals-rule', 'ap-calculus-bc/differentiation/3', 'ap-calculus-bc/differentiation', 'ap-calculus-bc', 'lhopitals-rule', 'L''Hôpital''s Rule', 'For indeterminate forms like 0/0 or ∞/∞, the limit of a quotient equals the limit of the quotient of the derivatives. Check the form before you use it.', '0/0', array['Verify the indeterminate form', 'Rewriting 0·∞ and 1^∞', 'Repeated application']::text[], array['lhopital', 'l''hospital', 'indeterminate forms']::text[], 14),
  ('riemann-sums', 'ap-calculus-bc/integration/1', 'ap-calculus-bc/integration', 'ap-calculus-bc', 'riemann-sums', 'Riemann Sums', 'A Riemann sum estimates area with rectangles or trapezoids. As the widths shrink, the sum approaches the definite integral.', 'Σ f(xᵢ)Δx', array['Left, right, midpoint', 'Trapezoidal sums', 'Over- or under-estimate?']::text[], array['rectangles', 'trapezoidal rule', 'area approximation']::text[], 15),
  ('fundamental-theorem-of-calculus', 'ap-calculus-bc/integration/1', 'ap-calculus-bc/integration', 'ap-calculus-bc', 'fundamental-theorem-of-calculus', 'Fundamental Theorem of Calculus', 'Differentiation and integration undo each other. Part 1 differentiates an accumulation function; Part 2 evaluates a definite integral with an antiderivative.', '∫ₐᵇ f′ = f(b)−f(a)', array['Accumulation functions', 'd/dx of an integral with variable bounds', 'Net change']::text[], array['FTC', 'ftc part 1', 'ftc part 2']::text[], 16),
  ('u-substitution', 'ap-calculus-bc/integration/2', 'ap-calculus-bc/integration', 'ap-calculus-bc', 'u-substitution', 'u-Substitution', 'u-substitution is the chain rule run backwards. Choose an inner function whose derivative also appears in the integrand, and the integral gets simpler.', 'u = g(x)', array['Choosing u', 'Changing the bounds', 'When it won''t work']::text[], array['substitution', 'u sub']::text[], 17),
  ('integration-by-parts', 'ap-calculus-bc/integration/2', 'ap-calculus-bc/integration', 'ap-calculus-bc', 'integration-by-parts', 'Integration by Parts', 'Integration by parts is the product rule run backwards: ∫u dv = uv − ∫v du. Choose u to be the factor that gets simpler when you differentiate it.', '∫u dv', array['LIATE as a heuristic', 'Tabular method', 'Loops that solve themselves']::text[], array['by parts', 'LIATE', 'tabular integration']::text[], 18),
  ('partial-fractions', 'ap-calculus-bc/integration/2', 'ap-calculus-bc/integration', 'ap-calculus-bc', 'partial-fractions', 'Partial Fractions', 'Split a rational function into simpler fractions that each integrate to a logarithm. BC only tests nonrepeated linear factors.', 'A/(x−a) + B/(x−b)', array['Factoring the denominator', 'Solving for A and B', 'Logistic connections']::text[], array['partial fraction decomposition']::text[], 19),
  ('area-between-curves', 'ap-calculus-bc/integration/3', 'ap-calculus-bc/integration', 'ap-calculus-bc', 'area-between-curves', 'Area Between Curves', 'The area between two curves is the integral of top minus bottom, or right minus left if you slice horizontally. Find the intersections first.', '∫(top − bottom)', array['Vertical vs. horizontal slices', 'Finding bounds', 'Regions that switch']::text[], array['area between two curves']::text[], 20),
  ('volumes-of-revolution', 'ap-calculus-bc/integration/3', 'ap-calculus-bc/integration', 'ap-calculus-bc', 'volumes-of-revolution', 'Volumes of Revolution', 'Spinning a region around an axis makes a solid. Use disks or washers with slices perpendicular to the axis, and measure each radius from the axis of rotation.', 'π∫R² − r²', array['Disks and washers', 'Rotating about y = k', 'Known cross sections']::text[], array['disk method', 'washer method', 'cross sections']::text[], 21),
  ('slope-fields', 'ap-calculus-bc/differential-equations/1', 'ap-calculus-bc/differential-equations', 'ap-calculus-bc', 'slope-fields', 'Slope Fields', 'A slope field shows a differential equation''s solutions without solving it. Every tiny segment has the slope dy/dx at that point.', '⟋⟍⟋', array['Sketching by hand', 'Matching fields to equations', 'Tracing a particular solution']::text[], array['direction fields']::text[], 22),
  ('separation-of-variables', 'ap-calculus-bc/differential-equations/1', 'ap-calculus-bc/differential-equations', 'ap-calculus-bc', 'separation-of-variables', 'Separation of Variables', 'Get every y on one side and every x on the other, integrate both sides, then use the initial condition to find the constant. It''s the most reliable free-response points on the exam.', 'dy/y = k dt', array['Separating cleanly', '+C at the right moment', 'Solving for y explicitly']::text[], array['separable differential equations', 'separable']::text[], 23),
  ('eulers-method', 'ap-calculus-bc/differential-equations/1', 'ap-calculus-bc/differential-equations', 'ap-calculus-bc', 'eulers-method', 'Euler''s Method', 'Euler''s method approximates a solution by taking small tangent-line steps. Concavity tells you whether each step over- or under-shoots.', 'yₙ₊₁ = yₙ + hf′', array['The step table', 'Step size tradeoffs', 'Over or under?']::text[], array['euler method', 'numerical approximation']::text[], 24),
  ('logistic-growth', 'ap-calculus-bc/differential-equations/1', 'ap-calculus-bc/differential-equations', 'ap-calculus-bc', 'logistic-growth', 'Logistic Growth', 'Logistic models grow fastest at half the carrying capacity and level off at L. You can read a lot from the equation without solving it.', 'kP(1 − P/L)', array['Carrying capacity', 'Fastest growth at L/2', 'Reading the equation']::text[], array['logistic differential equation', 'carrying capacity']::text[], 25),
  ('parametric-derivatives', 'ap-calculus-bc/parametric-polar-vector/1', 'ap-calculus-bc/parametric-polar-vector', 'ap-calculus-bc', 'parametric-derivatives', 'Parametric Derivatives', 'For a curve given by x(t) and y(t), the slope is dy/dt divided by dx/dt. The second derivative takes one more careful step.', '(dy/dt)/(dx/dt)', array['Slope from parametric equations', 'd²y/dx² without mistakes', 'Horizontal and vertical tangents']::text[], array['parametric equations', 'parametric second derivative']::text[], 26),
  ('vector-valued-motion', 'ap-calculus-bc/parametric-polar-vector/1', 'ap-calculus-bc/parametric-polar-vector', 'ap-calculus-bc', 'vector-valued-motion', 'Motion with Vectors', 'Position, velocity, and acceleration become vectors. Speed is the magnitude of the velocity vector, and total distance is the integral of speed.', '⟨x′(t), y′(t)⟩', array['Velocity and acceleration vectors', 'Speed vs. velocity', 'Arc length as distance']::text[], array['particle motion', 'vector functions', 'arc length']::text[], 27),
  ('polar-area', 'ap-calculus-bc/parametric-polar-vector/2', 'ap-calculus-bc/parametric-polar-vector', 'ap-calculus-bc', 'polar-area', 'Area in Polar Coordinates', 'In polar coordinates, area comes from thin sectors, so the formula is ½∫r² dθ. Getting the θ bounds right is most of the work.', '½∫r² dθ', array['Where the formula comes from', 'Finding θ bounds', 'Area between two polar curves']::text[], array['polar', 'polar curves', 'polar area']::text[], 28),
  ('ratio-test', 'ap-calculus-bc/infinite-series/1', 'ap-calculus-bc/infinite-series', 'ap-calculus-bc', 'ratio-test', 'The Ratio Test', 'The ratio test compares each term to the one before it. If the limiting ratio is below 1 the series converges; if it equals 1, the test tells you nothing.', '|aₙ₊₁/aₙ|', array['Factorials and exponentials', 'The inconclusive case', 'Setting up radius problems']::text[], array['ratio test series']::text[], 29),
  ('alternating-series', 'ap-calculus-bc/infinite-series/1', 'ap-calculus-bc/infinite-series', 'ap-calculus-bc', 'alternating-series', 'Alternating Series', 'An alternating series converges if its terms shrink to zero in size. The error from stopping early is at most the first term you left out.', 'Σ(−1)ⁿbₙ', array['The two conditions', 'Alternating series error bound', 'Absolute vs. conditional']::text[], array['alternating series test', 'AST', 'conditional convergence']::text[], 30),
  ('integral-and-comparison-tests', 'ap-calculus-bc/infinite-series/1', 'ap-calculus-bc/infinite-series', 'ap-calculus-bc', 'integral-and-comparison-tests', 'Integral and Comparison Tests', 'Compare an unfamiliar series to one you already know, like a p-series or a geometric series, or to an improper integral. The trick is picking the right comparison.', 'Σ 1/nᵖ', array['p-series benchmark', 'Direct vs. limit comparison', 'Integral test conditions']::text[], array['comparison test', 'p-series', 'limit comparison']::text[], 31),
  ('taylor-polynomials', 'ap-calculus-bc/infinite-series/2', 'ap-calculus-bc/infinite-series', 'ap-calculus-bc', 'taylor-polynomials', 'Taylor Polynomials', 'A Taylor polynomial matches a function''s value and derivatives at one point. The more terms you include, the longer it follows the curve.', 'f⁽ⁿ⁾(a)/n!', array['Building from derivatives', 'Maclaurin series to memorize', 'Manipulating known series']::text[], array['taylor series', 'maclaurin series', 'power series']::text[], 32),
  ('lagrange-error-bound', 'ap-calculus-bc/infinite-series/2', 'ap-calculus-bc/infinite-series', 'ap-calculus-bc', 'lagrange-error-bound', 'Lagrange Error Bound', 'The Lagrange error bound caps how far a Taylor polynomial can be from the true value. You need a bound M on the next derivative across the interval.', '|Rₙ| ≤ M/(n+1)!', array['Choosing M', 'The (n+1) details', 'Lagrange vs. alternating bound']::text[], array['error bound', 'taylor remainder']::text[], 33),
  ('radius-of-convergence', 'ap-calculus-bc/infinite-series/2', 'ap-calculus-bc/infinite-series', 'ap-calculus-bc', 'radius-of-convergence', 'Radius and Interval of Convergence', 'A power series converges within some radius of its center. Use the ratio test to find the radius, then test each endpoint on its own.', '|x − a| < R', array['Ratio test for radius', 'Checking endpoints', 'Interval notation']::text[], array['interval of convergence', 'radius']::text[], 34),
  ('champa-rice', 'ap-world-history/global-tapestry/1', 'ap-world-history/global-tapestry', 'ap-world-history', 'champa-rice', 'Champa Rice and Song China', 'Champa rice was a fast-ripening, drought-resistant rice from Vietnam that let Song farmers harvest twice a year. The surplus fed a population boom, bigger cities, and commercial growth.', '稻', array['Where Champa rice came from', 'Surplus → population → cities', 'Using it as DBQ evidence']::text[], array['song dynasty agriculture', 'fast ripening rice', 'song economy', 'vietnam rice']::text[], 1),
  ('song-bureaucracy', 'ap-world-history/global-tapestry/1', 'ap-world-history/global-tapestry', 'ap-world-history', 'song-bureaucracy', 'Song Bureaucracy and Neo-Confucianism', 'The Song ran China through a merit-based civil service chosen by exam. Neo-Confucianism reinforced hierarchy and filial piety across both state and family.', '科舉', array['The civil service exams', 'Neo-Confucian values', 'Continuity and change in governance']::text[], array['civil service exam', 'neo confucianism', 'song dynasty']::text[], 2),
  ('dar-al-islam', 'ap-world-history/global-tapestry/2', 'ap-world-history/global-tapestry', 'ap-world-history', 'dar-al-islam', 'Dar al-Islam', 'The Abbasid Caliphate broke apart, but the wider Islamic world stayed connected through trade, law, and learning. The House of Wisdom preserved and extended Greek, Persian, and Indian knowledge.', 'بيت الحكمة', array['Fragmentation of the Abbasids', 'Turkic states', 'Scholarly exchange']::text[], array['abbasid', 'house of wisdom', 'islamic world']::text[], 3),
  ('mali-empire', 'ap-world-history/global-tapestry/2', 'ap-world-history/global-tapestry', 'ap-world-history', 'mali-empire', 'Mali and Mansa Musa', 'Mali grew rich by controlling the trans-Saharan gold and salt trade. Mansa Musa''s 1324 hajj made that wealth famous across the Mediterranean.', '☼', array['Gold-salt trade', 'Timbuktu as a center of learning', 'Islam and state legitimacy']::text[], array['mansa musa', 'timbuktu', 'west africa', 'trans-saharan']::text[], 4),
  ('silk-roads', 'ap-world-history/networks-of-exchange/1', 'ap-world-history/networks-of-exchange', 'ap-world-history', 'silk-roads', 'The Silk Roads', 'The Silk Roads were a network of overland routes that carried luxury goods, religions, technologies, and disease across Eurasia. Caravanserai and credit systems made trading over long distances practical.', '⇄', array['Luxury goods and why', 'Caravanserai and flying cash', 'Cultural diffusion']::text[], array['silk road', 'overland trade', 'caravanserai']::text[], 5),
  ('indian-ocean-trade', 'ap-world-history/networks-of-exchange/1', 'ap-world-history/networks-of-exchange', 'ap-world-history', 'indian-ocean-trade', 'Indian Ocean Trade', 'Monsoon winds set the rhythm of Indian Ocean trade. Diaspora communities of merchants spread goods, faiths, and customs from East Africa to China.', '≈', array['Monsoon knowledge', 'Swahili city-states', 'Diasporic communities']::text[], array['monsoon', 'swahili coast', 'maritime trade']::text[], 6),
  ('mongol-empire', 'ap-world-history/networks-of-exchange/2', 'ap-world-history/networks-of-exchange', 'ap-world-history', 'mongol-empire', 'The Mongol Empire', 'The Mongols built the largest contiguous land empire in history. The Pax Mongolica made Eurasian trade safer, and it also helped the plague travel.', '⚑', array['Military innovation', 'Pax Mongolica', 'Transfers of technology and disease']::text[], array['genghis khan', 'pax mongolica', 'khanates']::text[], 7),
  ('gunpowder-empires', 'ap-world-history/land-based-empires/1', 'ap-world-history/land-based-empires', 'ap-world-history', 'gunpowder-empires', 'Ottomans, Safavids, and Mughals', 'Three Islamic empires used firearms to expand and hold territory. They legitimized rule in different ways and managed religiously diverse subjects differently.', '⚔', array['Military technology and expansion', 'Sunni–Shia rivalry', 'Akbar''s tolerance']::text[], array['ottoman empire', 'safavid', 'mughal', 'islamic empires']::text[], 8),
  ('devshirme', 'ap-world-history/land-based-empires/1', 'ap-world-history/land-based-empires', 'ap-world-history', 'devshirme', 'The Devshirme System', 'The Ottomans took Christian boys from the Balkans, converted them, and trained them as Janissaries or administrators. The system created an elite whose loyalty ran to the sultan alone.', '⚜', array['How it worked', 'Janissaries', 'Loyalty and centralization']::text[], array['janissaries', 'ottoman administration']::text[], 9),
  ('columbian-exchange', 'ap-world-history/transoceanic-interconnections/1', 'ap-world-history/transoceanic-interconnections', 'ap-world-history', 'columbian-exchange', 'The Columbian Exchange', 'After 1492, plants, animals, diseases, and people crossed the Atlantic in both directions. Smallpox devastated Indigenous populations, while American crops fed population growth in Afro-Eurasia.', '⇆', array['Disease and demographic collapse', 'Crops that changed diets', 'Cash crops and labor demand']::text[], array['columbian exchange', 'smallpox', 'potatoes maize']::text[], 10),
  ('labor-systems', 'ap-world-history/transoceanic-interconnections/1', 'ap-world-history/transoceanic-interconnections', 'ap-world-history', 'labor-systems', 'Encomienda, Hacienda, and Mit''a', 'Spanish colonizers adapted older labor systems and invented new ones to extract wealth. Knowing how each system differed is a reliable way to earn comparison points.', '⛏', array['Encomienda vs. hacienda', 'The mit''a and Potosí', 'Why labor was coerced']::text[], array['encomienda', 'hacienda', 'mita', 'potosi', 'coerced labor']::text[], 11),
  ('atlantic-slave-trade', 'ap-world-history/transoceanic-interconnections/1', 'ap-world-history/transoceanic-interconnections', 'ap-world-history', 'atlantic-slave-trade', 'The Atlantic Slave Trade', 'Plantation economies drove the forced migration of about 12 million Africans. The trade changed demographics and economies on three continents.', '△', array['Triangular trade', 'Plantation economies', 'Impact on West African states']::text[], array['transatlantic slave trade', 'middle passage', 'triangular trade']::text[], 12),
  ('enlightenment', 'ap-world-history/revolutions/1', 'ap-world-history/revolutions', 'ap-world-history', 'enlightenment', 'Enlightenment Ideas', 'Enlightenment thinkers questioned inherited authority and argued for natural rights and the social contract. Those ideas powered revolutions across the Atlantic world.', '¶', array['Locke, Rousseau, Montesquieu', 'Natural rights', 'From ideas to revolutions']::text[], array['locke', 'rousseau', 'social contract', 'natural rights']::text[], 13),
  ('haitian-revolution', 'ap-world-history/revolutions/1', 'ap-world-history/revolutions', 'ap-world-history', 'haitian-revolution', 'The Haitian Revolution', 'The only successful large-scale revolt of enslaved people founded an independent Haiti in 1804. It unsettled slaveholding societies across the hemisphere.', '✦', array['Saint-Domingue''s economy', 'Toussaint Louverture', 'Hemispheric consequences']::text[], array['haiti', 'toussaint louverture', 'saint domingue']::text[], 14),
  ('industrial-revolution', 'ap-world-history/revolutions/2', 'ap-world-history/revolutions', 'ap-world-history', 'industrial-revolution', 'Why Industrialization Began in Britain', 'Coal, capital, colonies, and a large supply of labor made Britain the first industrial economy. The AP exam wants multiple interacting causes, not a single one.', '⚙', array['Factors of production', 'Steam and coal', 'Causation reasoning']::text[], array['industrial revolution causes', 'britain industrialization', 'steam engine']::text[], 15),
  ('new-imperialism', 'ap-world-history/consequences-of-industrialization/1', 'ap-world-history/consequences-of-industrialization', 'ap-world-history', 'new-imperialism', 'New Imperialism', 'Industrial powers colonized Africa and Asia to secure raw materials and markets, and justified it with Social Darwinism. The Berlin Conference divided Africa without any Africans in the room.', '◐', array['Economic motives', 'Ideological justifications', 'Berlin Conference']::text[], array['scramble for africa', 'berlin conference', 'social darwinism', 'imperialism']::text[], 16),
  ('meiji-restoration', 'ap-world-history/consequences-of-industrialization/1', 'ap-world-history/consequences-of-industrialization', 'ap-world-history', 'meiji-restoration', 'The Meiji Restoration', 'After being forced open, Japan industrialized from the top down and became an imperial power within a generation. It''s the key counterexample in state-reform questions.', '明治', array['Why Japan reformed', 'State-led industrialization', 'Comparison with the Qing']::text[], array['meiji japan', 'japanese industrialization']::text[], 17),
  ('causes-of-wwi', 'ap-world-history/global-conflict/1', 'ap-world-history/global-conflict', 'ap-world-history', 'causes-of-wwi', 'Causes of World War I', 'Militarism, alliances, imperial rivalry, and nationalism made a regional crisis into a world war. The assassination in Sarajevo was the spark, not the cause.', 'M·A·I·N', array['Long-term vs. immediate causes', 'Alliance systems', 'Total war']::text[], array['wwi', 'world war 1', 'MAIN causes', 'franz ferdinand']::text[], 18),
  ('decolonization', 'ap-world-history/global-conflict/2', 'ap-world-history/global-conflict', 'ap-world-history', 'decolonization', 'Decolonization', 'After 1945, colonies across Asia and Africa won independence through negotiation or through armed struggle. Compare India, Algeria, and Ghana to see the range.', '↺', array['Negotiated vs. violent paths', 'Nationalist leaders', 'Cold War entanglements']::text[], array['independence movements', 'gandhi', 'algeria', 'ghana', 'nkrumah']::text[], 19),
  ('slope-intercept', 'sat-math/algebra/1', 'sat-math/algebra', 'sat-math', 'slope-intercept', 'Slope-Intercept Form', 'In y = mx + b, m is the rate of change and b is the starting value. Many SAT word problems are just asking you to read m and b from context.', 'y = mx + b', array['Interpreting slope in context', 'From two points to an equation', 'Parallel and perpendicular']::text[], array['linear equations', 'slope', 'y intercept', 'linear functions']::text[], 1),
  ('systems-of-equations', 'sat-math/algebra/1', 'sat-math/algebra', 'sat-math', 'systems-of-equations', 'Systems of Linear Equations', 'A system of two linear equations has one solution, no solution, or infinitely many. You can tell which by comparing slopes and intercepts, often without solving.', '{ 2x + y = 7', array['Elimination vs. substitution', 'No solution / infinite solutions', 'Solving in Desmos']::text[], array['systems', 'simultaneous equations', 'infinitely many solutions']::text[], 2),
  ('linear-inequalities', 'sat-math/algebra/1', 'sat-math/algebra', 'sat-math', 'linear-inequalities', 'Linear Inequalities', 'Inequalities work like equations, except the sign flips when you multiply or divide by a negative. SAT questions often pair them with a real-world constraint.', '≤', array['Flipping the sign', 'Graphing half-planes', 'Constraint word problems']::text[], array['inequalities', 'systems of inequalities']::text[], 3),
  ('quadratic-forms', 'sat-math/advanced-math/1', 'sat-math/advanced-math', 'sat-math', 'quadratic-forms', 'Three Forms of a Quadratic', 'Standard, factored, and vertex form each show something different: the y-intercept, the zeros, or the vertex. Choose the form that answers the question.', 'a(x − h)² + k', array['What each form reveals', 'Completing the square', 'Matching form to question']::text[], array['vertex form', 'factored form', 'standard form', 'parabola']::text[], 4),
  ('discriminant', 'sat-math/advanced-math/1', 'sat-math/advanced-math', 'sat-math', 'discriminant', 'The Discriminant', 'b² − 4ac tells you how many real solutions a quadratic has without solving it. It shows up a lot on questions with an unknown constant.', 'b² − 4ac', array['Positive, zero, negative', 'Tangent-line questions', 'Solving for the unknown constant']::text[], array['number of solutions', 'quadratic formula']::text[], 5),
  ('exponential-growth', 'sat-math/advanced-math/2', 'sat-math/advanced-math', 'sat-math', 'exponential-growth', 'Exponential Growth and Decay', 'Exponential functions change by the same percentage each period. Read the growth factor: 1.05 means 5% growth and 0.8 means 20% decay.', 'a(1 + r)ᵗ', array['Growth factor vs. rate', 'Linear vs. exponential', 'Changing the time unit']::text[], array['exponential decay', 'compound interest', 'percent growth']::text[], 6),
  ('function-notation', 'sat-math/advanced-math/3', 'sat-math/advanced-math', 'sat-math', 'function-notation', 'Function Notation and Composition', 'f(x) is an output, not multiplication. Composition means working from the inside out, and transformations shift the graph in predictable ways.', 'f(g(2))', array['Evaluating from tables and graphs', 'Inside-out composition', 'Shifts and reflections']::text[], array['functions', 'composition', 'transformations']::text[], 7),
  ('percent-change', 'sat-math/problem-solving-data/1', 'sat-math/problem-solving-data', 'sat-math', 'percent-change', 'Percent Change', 'Percent change is (new − old) / old. Stacked percent changes multiply rather than add, and that''s where most SAT traps are.', '%Δ', array['The multiplier method', 'Successive changes', 'Percent of vs. percent more than']::text[], array['percentages', 'percent increase', 'percent decrease']::text[], 8),
  ('unit-conversion', 'sat-math/problem-solving-data/1', 'sat-math/problem-solving-data', 'sat-math', 'unit-conversion', 'Rates and Unit Conversion', 'Chain the conversion factors so the unwanted units cancel. Writing out the units keeps you from dividing when you should multiply.', 'mi/h → ft/s', array['Dimensional analysis', 'Square and cubic units', 'Density and rate problems']::text[], array['unit conversions', 'rates', 'dimensional analysis']::text[], 9),
  ('center-and-spread', 'sat-math/problem-solving-data/2', 'sat-math/problem-solving-data', 'sat-math', 'center-and-spread', 'Mean, Median, and Spread', 'The mean is pulled by outliers and the median isn''t. The SAT asks how adding or removing a value changes each one and the standard deviation.', 'x̄  σ', array['Outliers and the mean', 'Reading spread', 'Comparing distributions']::text[], array['mean median mode', 'standard deviation', 'statistics', 'outliers']::text[], 10),
  ('two-way-tables', 'sat-math/problem-solving-data/2', 'sat-math/problem-solving-data', 'sat-math', 'two-way-tables', 'Two-Way Tables and Probability', 'Conditional probability means restricting to a row or a column first. Find the denominator the question describes before you compute anything.', 'P(A | B)', array['Finding the right total', 'Conditional probability', 'Sampling and inference']::text[], array['probability', 'conditional probability', 'contingency table']::text[], 11),
  ('right-triangle-trig', 'sat-math/geometry-trig/1', 'sat-math/geometry-trig', 'sat-math', 'right-triangle-trig', 'Right Triangle Trigonometry', 'Sine, cosine, and tangent are ratios of sides. The SAT likes the identity sin(x) = cos(90° − x) and the special 30-60-90 and 45-45-90 triangles.', 'SOH·CAH·TOA', array['SOH CAH TOA', 'Complementary angle identity', 'Special right triangles']::text[], array['trigonometry', 'sohcahtoa', 'special right triangles', 'trig']::text[], 12),
  ('similar-triangles', 'sat-math/geometry-trig/1', 'sat-math/geometry-trig', 'sat-math', 'similar-triangles', 'Similar Triangles', 'Similar triangles have equal angles and proportional sides. Match corresponding vertices carefully, then set up one proportion.', '△ ∼ △', array['AA similarity', 'Setting up proportions', 'Area scales with k²']::text[], array['similarity', 'proportional triangles']::text[], 13),
  ('circle-equations', 'sat-math/geometry-trig/2', 'sat-math/geometry-trig', 'sat-math', 'circle-equations', 'Equations of Circles', 'A circle centered at (h, k) with radius r is (x − h)² + (y − k)² = r². When it''s given expanded, complete the square to find the center.', '(x − h)² + (y − k)²', array['Reading center and radius', 'Completing the square twice', 'Arc length and sectors']::text[], array['circles', 'equation of a circle', 'arc length', 'radians']::text[], 14),
  ('enzyme-kinetics', 'ap-biology/cellular-energetics/1', 'ap-biology/cellular-energetics', 'ap-biology', 'enzyme-kinetics', 'Enzymes and Activation Energy', 'Enzymes speed up reactions by lowering activation energy. Temperature, pH, and inhibitors all work by changing the shape of the active site.', 'E + S ⇌ ES', array['Active site specificity', 'Denaturation', 'Competitive vs. noncompetitive inhibition']::text[], array['enzymes', 'activation energy', 'inhibitors']::text[], 1),
  ('photosynthesis', 'ap-biology/cellular-energetics/2', 'ap-biology/cellular-energetics', 'ap-biology', 'photosynthesis', 'Photosynthesis', 'The light reactions capture energy as ATP and NADPH, and the Calvin cycle uses them to fix CO₂ into sugar. Track where each molecule goes.', 'hν → ATP', array['Light-dependent reactions', 'The Calvin cycle', 'Chemiosmosis in the chloroplast']::text[], array['light reactions', 'calvin cycle', 'chloroplast']::text[], 2),
  ('cellular-respiration', 'ap-biology/cellular-energetics/2', 'ap-biology/cellular-energetics', 'ap-biology', 'cellular-respiration', 'Cellular Respiration', 'Glycolysis, the Krebs cycle, and oxidative phosphorylation release energy from glucose in steps. Most of the ATP comes from a proton gradient.', 'C₆H₁₂O₆ → ATP', array['Glycolysis and pyruvate oxidation', 'Electron transport chain', 'Fermentation']::text[], array['krebs cycle', 'electron transport chain', 'atp synthase', 'glycolysis']::text[], 3),
  ('meiosis', 'ap-biology/heredity/1', 'ap-biology/heredity', 'ap-biology', 'meiosis', 'Meiosis and Genetic Variation', 'Meiosis makes four genetically unique haploid cells. Crossing over and independent assortment are where the variation comes from.', '2n → n', array['Meiosis I vs. II', 'Crossing over', 'Nondisjunction']::text[], array['crossing over', 'independent assortment', 'gametes']::text[], 4),
  ('mendelian-genetics', 'ap-biology/heredity/1', 'ap-biology/heredity', 'ap-biology', 'mendelian-genetics', 'Mendelian Genetics and Chi-Square', 'Punnett squares predict ratios, and chi-square tests whether the observed data really fit them. Both show up in free response almost every year.', 'χ²', array['Monohybrid and dihybrid crosses', 'Linked genes', 'Running a chi-square test']::text[], array['punnett square', 'chi square', 'mendel', 'dihybrid']::text[], 5),
  ('transcription-translation', 'ap-biology/gene-expression/1', 'ap-biology/gene-expression', 'ap-biology', 'transcription-translation', 'Transcription and Translation', 'RNA polymerase transcribes DNA into mRNA, and ribosomes translate the mRNA into protein. In eukaryotes the mRNA is processed before it leaves the nucleus.', 'DNA → RNA → ⬡', array['Template vs. coding strand', 'mRNA processing', 'Codons and tRNA']::text[], array['central dogma', 'protein synthesis', 'mrna']::text[], 6),
  ('operons', 'ap-biology/gene-expression/1', 'ap-biology/gene-expression', 'ap-biology', 'operons', 'Operons and Gene Regulation', 'Bacteria turn groups of genes on or off together. The lac operon is inducible and the trp operon is repressible, and the exam loves comparing them.', 'lac', array['Repressors and inducers', 'lac vs. trp', 'Eukaryotic regulation']::text[], array['lac operon', 'trp operon', 'gene regulation']::text[], 7),
  ('hardy-weinberg', 'ap-biology/natural-selection/1', 'ap-biology/natural-selection', 'ap-biology', 'hardy-weinberg', 'Hardy-Weinberg Equilibrium', 'Hardy-Weinberg describes a population that isn''t evolving. Compare real allele frequencies to it to see evolution happening.', 'p² + 2pq + q²', array['The five conditions', 'Solving from q²', 'What deviations mean']::text[], array['hardy weinberg', 'allele frequency', 'population genetics']::text[], 8),
  ('electron-configuration', 'ap-chemistry/atomic-structure/1', 'ap-chemistry/atomic-structure', 'ap-chemistry', 'electron-configuration', 'Electron Configuration and PES', 'Electron configurations show which subshells are filled. Photoelectron spectroscopy measures those energies directly.', '1s² 2s² 2p⁶', array['Aufbau order', 'Reading a PES graph', 'Ions and exceptions']::text[], array['pes', 'photoelectron spectroscopy', 'orbitals']::text[], 1),
  ('periodic-trends', 'ap-chemistry/atomic-structure/1', 'ap-chemistry/atomic-structure', 'ap-chemistry', 'periodic-trends', 'Periodic Trends', 'Atomic radius, ionization energy, and electronegativity all follow from Coulomb''s law. Explain every trend with effective nuclear charge and distance.', 'Zeff', array['Coulomb''s law reasoning', 'Shielding', 'Ionization energy exceptions']::text[], array['atomic radius', 'ionization energy', 'electronegativity']::text[], 2),
  ('vsepr', 'ap-chemistry/bonding/1', 'ap-chemistry/bonding', 'ap-chemistry', 'vsepr', 'Lewis Structures and VSEPR', 'Draw the Lewis structure, count the electron domains, and VSEPR gives you the shape. Formal charge helps you choose between possible structures.', '⌬', array['Counting electron domains', 'Formal charge', 'Polarity from shape']::text[], array['lewis structure', 'molecular geometry', 'formal charge']::text[], 3),
  ('intermolecular-forces', 'ap-chemistry/bonding/1', 'ap-chemistry/bonding', 'ap-chemistry', 'intermolecular-forces', 'Intermolecular Forces', 'London dispersion forces, dipole-dipole attractions, and hydrogen bonding explain boiling points and solubility. Always name the specific force.', 'δ+ ··· δ−', array['Ranking IMF strength', 'Polarizability', 'Boiling point justifications']::text[], array['imf', 'hydrogen bonding', 'london dispersion']::text[], 4),
  ('le-chatelier', 'ap-chemistry/equilibrium/1', 'ap-chemistry/equilibrium', 'ap-chemistry', 'le-chatelier', 'Le Châtelier''s Principle', 'When you disturb a system at equilibrium, it shifts to partly undo the change. Explain the shift by comparing Q to K.', '⇌', array['Concentration and pressure changes', 'Temperature changes K', 'Q vs. K']::text[], array['le chatelier', 'equilibrium shift', 'reaction quotient']::text[], 5),
  ('ice-tables', 'ap-chemistry/equilibrium/1', 'ap-chemistry/equilibrium', 'ap-chemistry', 'ice-tables', 'ICE Tables', 'An ICE table lays out the initial amounts, the change, and the equilibrium amounts, so you can solve for concentrations. Check whether the small-x approximation holds.', 'I · C · E', array['Setting up the table', 'Small-x approximation', 'Solving for K']::text[], array['ice table', 'equilibrium calculations']::text[], 6),
  ('buffers', 'ap-chemistry/acids-bases/1', 'ap-chemistry/acids-bases', 'ap-chemistry', 'buffers', 'Buffers and Henderson–Hasselbalch', 'A buffer resists pH change because it contains both a weak acid and its conjugate base. When the two are equal, pH = pKa.', 'pKa + log(A⁻/HA)', array['Why buffers work', 'Henderson–Hasselbalch', 'Buffer capacity']::text[], array['henderson hasselbalch', 'buffer', 'pka']::text[], 7),
  ('titration-curves', 'ap-chemistry/acids-bases/1', 'ap-chemistry/acids-bases', 'ap-chemistry', 'titration-curves', 'Titration Curves', 'A titration curve shows the equivalence point and the half-equivalence point, where pH = pKa. Its shape tells you whether the acid is strong or weak.', '⟋⎯⟋', array['Equivalence point', 'Half-equivalence', 'Choosing an indicator']::text[], array['titration', 'equivalence point']::text[], 8),
  ('gibbs-free-energy', 'ap-chemistry/thermodynamics/1', 'ap-chemistry/thermodynamics', 'ap-chemistry', 'gibbs-free-energy', 'Gibbs Free Energy', 'ΔG combines enthalpy and entropy to predict whether a process is thermodynamically favorable. Its sign can flip with temperature.', 'ΔG = ΔH − TΔS', array['Signs of ΔH and ΔS', 'Temperature dependence', 'ΔG° and K']::text[], array['gibbs', 'free energy', 'entropy', 'thermodynamically favorable']::text[], 9),
  ('words-in-context', 'sat-reading-writing/craft-and-structure/1', 'sat-reading-writing/craft-and-structure', 'sat-reading-writing', 'words-in-context', 'Words in Context', 'Predict a word for the blank before you look at the choices, then match. The right answer fits the logic of the passage, not only its tone.', '___', array['Predict first', 'Contrast and continuation clues', 'Eliminating near-synonyms']::text[], array['vocabulary', 'vocab in context', 'fill in the blank']::text[], 1),
  ('text-structure-purpose', 'sat-reading-writing/craft-and-structure/1', 'sat-reading-writing/craft-and-structure', 'sat-reading-writing', 'text-structure-purpose', 'Text Structure and Purpose', 'Ask what each sentence does, not what it says. Structure questions reward naming the move the author is making.', '¶ → ¶', array['Function vs. content', 'Common structures', 'Main purpose']::text[], array['purpose', 'function of sentence', 'structure']::text[], 2),
  ('command-of-evidence', 'sat-reading-writing/information-and-ideas/1', 'sat-reading-writing/information-and-ideas', 'sat-reading-writing', 'command-of-evidence', 'Command of Evidence: Quantitative', 'These questions pair a claim with a table or graph. The answer has to be true according to the data and has to support the specific claim being made.', '▥', array['Restate the claim', 'Read the exact data point', 'True but irrelevant traps']::text[], array['graphs', 'data questions', 'quantitative evidence', 'tables']::text[], 3),
  ('inferences', 'sat-reading-writing/information-and-ideas/1', 'sat-reading-writing/information-and-ideas', 'sat-reading-writing', 'inferences', 'Inferences', 'Complete the passage''s reasoning with the choice that must follow logically. Anything that goes beyond the passage is wrong, even if it sounds plausible.', '∴', array['Tracing the argument', 'Must be true vs. could be true', 'Hedged language']::text[], array['logical completion', 'inference questions']::text[], 4),
  ('semicolons-colons', 'sat-reading-writing/standard-english-conventions/1', 'sat-reading-writing/standard-english-conventions', 'sat-reading-writing', 'semicolons-colons', 'Semicolons, Colons, and Dashes', 'A semicolon joins two complete sentences. A colon introduces something that explains what came before it. Test each side for independence.', '; : —', array['Independent clause test', 'Colon as an arrow', 'Paired dashes']::text[], array['punctuation', 'semicolon', 'colon', 'boundaries', 'run on']::text[], 5),
  ('subject-verb-agreement', 'sat-reading-writing/standard-english-conventions/1', 'sat-reading-writing/standard-english-conventions', 'sat-reading-writing', 'subject-verb-agreement', 'Subject–Verb Agreement', 'Find the true subject by crossing out the prepositional phrases and the interrupters in between. Then match the verb to it.', 'S ↔ V', array['Cross out the middle', 'Collective nouns', 'Inverted sentences']::text[], array['agreement', 'verbs', 'grammar']::text[], 6),
  ('transitions', 'sat-reading-writing/standard-english-conventions/1', 'sat-reading-writing/standard-english-conventions', 'sat-reading-writing', 'transitions', 'Transitions', 'Figure out how the two sentences relate (contrast, continuation, cause, or example) before you look at the words. Then pick the transition that names that relationship.', '→', array['Name the relationship', 'Contrast vs. concession', 'Rhetorical synthesis']::text[], array['transition words', 'however therefore', 'rhetorical synthesis']::text[], 7)
insert into public.educators (id, handle, name, headline, bio, subjects, course_ids, credentials, rating, rating_count, hourly_rate, years_teaching, location, response_time, accepting_students, booking_url, hue) values
  ('edu_sarah-chen', 'sarah-chen', 'Sarah Chen', 'Calculus teacher who makes the notation disappear', 'I taught AP Calculus BC for nine years at a public magnet school in Oakland, and 94% of my students passed. I explain every idea twice: once as a picture, once as algebra. Most students who struggle with calculus are really struggling with the notation, and that part is fixable.', array['Calculus', 'Precalculus', 'SAT Math']::text[], array['ap-calculus-bc', 'sat-math']::text[], array['M.A. Mathematics Education, UC Berkeley', 'AP Reader, Calculus (6 years)']::text[], 4.97, 312, 85, 11, 'Oakland, CA', 'Usually replies within a few hours', true, null, 232),
  ('edu_marcus-okafor', 'marcus-okafor', 'Marcus Okafor', 'Former engineer, worked-examples specialist', 'I spent six years as a structural engineer before I started teaching. My lessons are built on worked examples: I solve the problem in front of you, say out loud every decision I make, then you try the next one.', array['Calculus', 'Physics', 'SAT Math']::text[], array['ap-calculus-bc', 'sat-math']::text[], array['B.S. Civil Engineering, Georgia Tech', 'Teaching since 2017']::text[], 4.91, 204, 70, 8, 'Atlanta, GA', 'Usually replies within a day', true, null, 20),
  ('edu_priya-raman', 'priya-raman', 'Priya Raman', 'Series and proofs, taught calmly', 'I''m finishing a math PhD, and I tutor because I like watching the moment when a proof finally makes sense. Series is my favorite unit to teach because it''s the one students fear most, and it doesn''t need to be.', array['Calculus', 'Real Analysis']::text[], array['ap-calculus-bc']::text[], array['Ph.D. candidate, Mathematics, University of Michigan']::text[], 4.95, 128, 90, 6, 'Ann Arbor, MI', 'Usually replies within a day', true, null, 280),
  ('edu_daniel-reyes', 'daniel-reyes', 'Daniel Reyes', 'AP World teacher. Big picture first, then evidence.', 'I''ve taught AP World History for twelve years in Houston and have read DBQs at the AP Reading for five of them. I teach history as arguments about causation and change, because that''s how the exam grades it.', array['World History', 'US History']::text[], array['ap-world-history']::text[], array['AP Reader, World History (5 years)', 'M.Ed., University of Houston']::text[], 4.96, 276, 75, 12, 'Houston, TX', 'Usually replies within a few hours', true, null, 28),
  ('edu_amara-bello', 'amara-bello', 'Amara Bello', 'Historian of trade networks and empire', 'My research is on Indian Ocean commerce, so I think about the past as a set of connections. My videos are short on purpose: one idea, three pieces of evidence, and how to use them in an essay.', array['World History', 'African History']::text[], array['ap-world-history']::text[], array['Ph.D. History, Northwestern', 'Former AP World teacher']::text[], 4.93, 141, 80, 9, 'Chicago, IL', 'Usually replies within a day', true, null, 12),
  ('edu_tom-lindqvist', 'tom-lindqvist', 'Tom Lindqvist', 'Timelines, maps, and the reasoning behind them', 'I''m a high school history teacher who draws everything. If you''re a visual learner, my maps and timelines are made for you.', array['World History', 'European History']::text[], array['ap-world-history']::text[], array['M.A. History, University of Minnesota']::text[], 4.84, 97, 60, 7, 'Minneapolis, MN', 'Usually replies within 2 days', false, null, 200),
  ('edu_jordan-kim', 'jordan-kim', 'Jordan Kim', 'SAT strategist, 1580 → full-time tutor', 'I''ve tutored the SAT full time for seven years and taken the digital version four times. I teach the fastest reliable method for each question type, including when to hand the problem to Desmos.', array['SAT Math', 'SAT Reading & Writing']::text[], array['sat-math', 'sat-reading-writing']::text[], array['1580 SAT', 'B.A. Economics, UCLA', '2,000+ hours tutoring']::text[], 4.94, 389, 95, 7, 'Los Angeles, CA', 'Usually replies within a few hours', true, null, 160),
  ('edu_elena-vasquez', 'elena-vasquez', 'Elena Vasquez', 'Grammar without the jargon', 'I taught high school English for ten years and I edit for a living now. The SAT tests the same small set of rules again and again, and I''ll show you how to hear them.', array['SAT Reading & Writing', 'English']::text[], array['sat-reading-writing']::text[], array['M.A. English, UT Austin', 'Former department head']::text[], 4.92, 173, 65, 10, 'Austin, TX', 'Usually replies within a day', true, null, 330),
  ('edu_nia-thompson', 'nia-thompson', 'Nia Thompson', 'Biology through experiments you can picture', 'I was a molecular biology researcher and now teach AP Bio in Baltimore. I explain processes as stories, with molecules as characters and clear causes and effects, because that''s how the free-response questions are written.', array['Biology', 'Biochemistry']::text[], array['ap-biology']::text[], array['M.S. Molecular Biology, Johns Hopkins', 'AP Biology teacher']::text[], 4.95, 158, 70, 8, 'Baltimore, MD', 'Usually replies within a day', true, null, 140),
  ('edu_sam-patel', 'sam-patel', 'Sam Patel', 'Pre-med who tutors bio and chem on the side', 'I got 5s in AP Bio and AP Chem three years ago, so I remember what was actually confusing. My videos are fast and practical, and they cover the questions my students ask most.', array['Biology', 'Chemistry']::text[], array['ap-biology', 'ap-chemistry']::text[], array['B.S. Biochemistry (in progress), Duke']::text[], 4.81, 64, 45, 3, 'Durham, NC', 'Usually replies within a few hours', true, null, 48),
  ('edu_hannah-weiss', 'hannah-weiss', 'Hannah Weiss', 'Chemistry is Coulomb''s law, over and over', 'I taught chemistry for fourteen years before moving to curriculum design. Almost every AP Chem explanation comes back to charge and distance, and once you see that, the whole course gets smaller.', array['Chemistry', 'Physics']::text[], array['ap-chemistry']::text[], array['M.S. Chemistry, University of Wisconsin', 'National Board Certified']::text[], 4.98, 221, 80, 14, 'Madison, WI', 'Usually replies within a day', true, null, 196)
